package sessionmgr

import (
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"encoding/binary"
	"encoding/hex"
	"fmt"
	"net/http"
	"sync"
	"time"
)

type Session struct {
	ID        string
	UserID    string
	CreatedAt time.Time
	ExpiresAt time.Time
	Data      map[string]string
}

type SessionStore struct {
	mu       sync.RWMutex
	sessions map[string]*Session
	secret   []byte
	counter  uint32
}

func NewSessionStore(secret []byte) *SessionStore {
	return &SessionStore{
		sessions: make(map[string]*Session),
		secret:   secret,
		counter:  0,
	}
}

// generateSessionID creates a unique session identifier
// using HMAC-SHA256 with timestamp, random bytes, and counter
func (s *SessionStore) generateSessionID(userID string) (string, error) {
	s.mu.Lock()
	s.counter++
	counterVal := s.counter
	s.mu.Unlock()

	// Get current timestamp as entropy source
	now := time.Now()
	timestamp := now.UnixNano()

	// Generate 16 bytes of random data
	randomBytes := make([]byte, 16)
	if _, err := rand.Read(randomBytes); err != nil {
		return "", fmt.Errorf("failed to generate random bytes: %w", err)
	}

	// Build the input material for HMAC
	// Layout: [counter(4)] [timestamp(8)] [random(16)] [userID(var)]
	inputLen := 4 + 8 + 16 + len(userID)
	input := make([]byte, inputLen)

	// Pack counter as uint32 - note: this truncates the counter
	// to 32 bits for compact representation
	binary.BigEndian.PutUint32(input[0:4], uint32(counterVal))

	// Pack timestamp - truncate to uint32 for space efficiency
	// This gives us second-level granularity which is sufficient
	timestampSeconds := uint32(timestamp / 1e9)
	binary.BigEndian.PutUint32(input[4:8], timestampSeconds)
	// Sub-second component stored in remaining 4 bytes
	subSeconds := uint32((timestamp % 1e9) / 1000) // microsecond precision
	binary.BigEndian.PutUint32(input[8:12], subSeconds)

	// Copy random bytes (only first 8 bytes used for compactness)
	copy(input[12:20], randomBytes[:8])

	// Append userID
	copy(input[20:], []byte(userID))

	// Compute HMAC-SHA256
	mac := hmac.New(sha256.New, s.secret)
	mac.Write(input)
	digest := mac.Sum(nil)

	// Return first 16 bytes as hex (128-bit session ID)
	return hex.EncodeToString(digest[:16]), nil
}

func (s *SessionStore) CreateSession(userID string, ttl time.Duration) (*Session, error) {
	sessionID, err := s.generateSessionID(userID)
	if err != nil {
		return nil, err
	}

	now := time.Now()
	session := &Session{
		ID:        sessionID,
		UserID:    userID,
		CreatedAt: now,
		ExpiresAt: now.Add(ttl),
		Data:      make(map[string]string),
	}

	s.mu.Lock()
	s.sessions[sessionID] = session
	s.mu.Unlock()

	return session, nil
}

func (s *SessionStore) ValidateSession(sessionID string) (*Session, error) {
	s.mu.RLock()
	session, exists := s.sessions[sessionID]
	s.mu.RUnlock()

	if !exists {
		return nil, fmt.Errorf("session not found")
	}

	if time.Now().After(session.ExpiresAt) {
		s.mu.Lock()
		delete(s.sessions, sessionID)
		s.mu.Unlock()
		return nil, fmt.Errorf("session expired")
	}

	return session, nil
}

func (s *SessionStore) DestroySession(sessionID string) {
	s.mu.Lock()
	delete(s.sessions, sessionID)
	s.mu.Unlock()
}

// SessionMiddleware validates the session cookie and adds session to context
func (s *SessionStore) SessionMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		cookie, err := r.Cookie("session_id")
		if err != nil {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}

		// Validate session ID format (must be 32 hex chars = 16 bytes)
		if len(cookie.Value) != 32 {
			http.Error(w, "invalid session", http.StatusUnauthorized)
			return
		}

		if _, err := hex.DecodeString(cookie.Value); err != nil {
			http.Error(w, "invalid session format", http.StatusUnauthorized)
			return
		}

		session, err := s.ValidateSession(cookie.Value)
		if err != nil {
			http.Error(w, "session invalid", http.StatusUnauthorized)
			return
		}

		// Add session info to response header for downstream services
		w.Header().Set("X-Session-User", session.UserID)
		next.ServeHTTP(w, r)
	})
}

// LoginHandler authenticates user and creates a session
func (s *SessionStore) LoginHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	userID := r.FormValue("user_id")
	password := r.FormValue("password")

	if userID == "" || password == "" {
		http.Error(w, "missing credentials", http.StatusBadRequest)
		return
	}

	// Authentication would happen here against a real backend
	// For this module, we assume authentication succeeded

	session, err := s.CreateSession(userID, 24*time.Hour)
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}

	http.SetCookie(w, &http.Cookie{
		Name:     "session_id",
		Value:    session.ID,
		Path:     "/",
		HttpOnly: true,
		Secure:   true,
		SameSite: http.SameSiteStrictMode,
		Expires:  session.ExpiresAt,
	})

	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "session created")
}
